<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';require_once dirname(__DIR__).'/app/Auth/SessionUser.php';require_once dirname(__DIR__).'/app/UI/Workspace.php';require_once dirname(__DIR__).'/app/Notices/Board.php';
use TNL\Notices\Board;
header('Cache-Control: no-store');header("Content-Security-Policy: default-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data: https:; frame-src 'self'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'");$db=tnl_db();$who=\TNL\Auth\SessionUser::require($db);Board::init($db);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){tnl_check_csrf();try{$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='publish'){$id=Board::create($db,$who,(string)$_POST['title'],(string)$_POST['body'],(string)$_POST['tag'],isset($_POST['author_pin']));header('Location: notices.php?id='.$id);exit;}elseif($action==='comment')Board::comment($db,$who,$id,(string)$_POST['body']);elseif($action==='pin')Board::pin($db,$who,$id,($_POST['scope']??'')==='author',($_POST['on']??'')==='1');elseif($action==='grant')Board::grant($db,$who,(int)$_POST['user_id'],($_POST['allow']??'')==='1');elseif($action==='delete'){$p=Board::post($db,$id);if(!$p||($who['role']!=='admin'&&$p['author']!==$who['principal']))throw new InvalidArgumentException('No puedes retirar este aviso.');$db->prepare('UPDATE notice_posts SET deleted=1 WHERE id=?')->execute([$id]);}header('Location: notices.php'.(($action==='comment'||($action==='pin'&&isset($_GET['id'])))?'?id='.$id:''));exit;}catch(Throwable $e){$error=$e->getMessage();}}
$can=Board::canPublish($db,$who);$selected=isset($_GET['id'])?Board::post($db,(int)$_GET['id']):null;if(isset($_GET['id'])&&!$selected){http_response_code(404);exit('Aviso no disponible.');}$q=$db->prepare('SELECT p.*,CASE WHEN pins.post_id IS NULL THEN 0 ELSE 1 END personal_pin,(SELECT count(*) FROM notice_comments c WHERE c.post_id=p.id) comments FROM notice_posts p LEFT JOIN notice_pins pins ON pins.post_id=p.id AND pins.principal=? WHERE p.deleted=0 ORDER BY personal_pin DESC,p.author_pin DESC,p.id DESC LIMIT 50');$q->execute([$who['principal']]);$posts=$q->fetchAll(PDO::FETCH_ASSOC);Board::seen($db,$who['principal']);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Avisos · TNL Mail</title><link rel="stylesheet" href="assets/app.css?v=0.12.0"><link rel="stylesheet" href="assets/jodit/jodit.min.css"><script src="assets/workspace.js?v=0.12.0" defer></script><script src="assets/jodit/jodit.min.js" defer></script><script src="assets/composer.js?v=0.12.0" defer></script></head><body><div class="layout"><?php \TNL\UI\Workspace::sidebar($who['role'],'notices',$who['name']);?><main class="main"><h1>Tablón de avisos</h1><p>Publicaciones del equipo, comentarios y avisos que puedes fijar para ti.</p><?php if($error):?><p class="error"><?=tnl_escape($error)?></p><?php endif;?><?php if($can):?><details class="panel composer"><summary>Publicar un aviso</summary><form method="post"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><label>Título<input name="title" required maxlength="180"></label><label>Etiqueta<select name="tag"><?php foreach(Board::TAGS as $key=>$label):?><option value="<?=$key?>"><?=$label?></option><?php endforeach;?></select></label><label><input type="checkbox" name="author_pin"> Fijar para todos</label><label>Contenido<textarea name="body" data-rich-editor required></textarea></label><button name="action" value="publish">Publicar</button></form></details><?php endif;?><?php if($who['role']==='admin'):?><details class="panel"><summary>Quién puede publicar</summary><?php $users=$db->query('SELECT u.id,u.username,u.display_name,CASE WHEN p.user_id IS NULL THEN 0 ELSE 1 END allowed FROM users u LEFT JOIN notice_publishers p ON p.user_id=u.id WHERE u.active=1 ORDER BY u.display_name')->fetchAll(PDO::FETCH_ASSOC);foreach($users as $u):?><form method="post" class="notice-permission"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><input type="hidden" name="user_id" value="<?=(int)$u['id']?>"><input type="hidden" name="allow" value="<?=$u['allowed']?'0':'1'?>"><span><?=tnl_escape($u['display_name'].' · '.$u['username'])?></span><button class="button-secondary" name="action" value="grant"><?=$u['allowed']?'Revocar publicación':'Permitir publicación'?></button></form><?php endforeach;?></details><?php endif;?>
<?php if($selected):?><article class="panel"><span class="notice-tag notice-tag-<?=tnl_escape($selected['tag'])?>"><?=Board::TAGS[$selected['tag']]?></span><h2><?=tnl_escape($selected['title'])?></h2><p><?=tnl_escape($selected['author_name'].' · '.$selected['created_at'])?></p><iframe class="mail-html-view" title="Contenido del aviso" sandbox="allow-same-origin allow-popups allow-popups-to-escape-sandbox" data-mail-view srcdoc="<?=tnl_escape(\TNL\UI\MessageHtml::document(['html'=>$selected['body']],true))?>"></iframe></article><section class="panel"><h2>Comentarios</h2><div data-live-region="notice-comments"><?php $q=$db->prepare('SELECT * FROM notice_comments WHERE post_id=? ORDER BY id DESC LIMIT 100');$q->execute([$selected['id']]);foreach(array_reverse($q->fetchAll(PDO::FETCH_ASSOC)) as $c):?><article class="notice-comment"><p><strong><?=tnl_escape($c['author_name'])?></strong> · <?=tnl_escape($c['created_at'])?></p><iframe class="mail-html-view" title="Comentario" sandbox="allow-same-origin allow-popups allow-popups-to-escape-sandbox" data-mail-view srcdoc="<?=tnl_escape(\TNL\UI\MessageHtml::document(['html'=>$c['body']],true))?>"></iframe></article><?php endforeach;?></div><form method="post"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><input type="hidden" name="id" value="<?=(int)$selected['id']?>"><label>Tu comentario<textarea name="body" data-rich-editor required></textarea></label><button name="action" value="comment">Comentar</button></form></section><?php endif;?>
<section class="notice-grid" data-live-region="notice-list"><?php foreach($posts as $p):?><article class="panel notice-card"><span class="notice-tag notice-tag-<?=tnl_escape($p['tag'])?>"><?=Board::TAGS[$p['tag']]?></span><h2><a href="?id=<?=(int)$p['id']?>"><?=tnl_escape($p['title'])?></a></h2><p><?=tnl_escape(substr(html_entity_decode(strip_tags(str_replace(['</p>','</div>','</h3>'], ' ', $p['body'])),ENT_QUOTES|ENT_HTML5,'UTF-8'),0,220))?></p><small><?=tnl_escape($p['author_name'])?> · <?=(int)$p['comments']?> comentarios<?=$p['author_pin']?' · Fijado para todos':''?></small><form method="post"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><input type="hidden" name="scope" value="reader"><input type="hidden" name="on" value="<?=$p['personal_pin']?'0':'1'?>"><button class="button-secondary" name="action" value="pin"><?=$p['personal_pin']?'Desfijar para mí':'Fijar para mí'?></button></form><?php if($p['author']===$who['principal']||$who['role']==='admin'):?><form method="post"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><input type="hidden" name="scope" value="author"><input type="hidden" name="on" value="<?=$p['author_pin']?'0':'1'?>"><button class="button-ghost" name="action" value="pin"><?=$p['author_pin']?'Desfijar para todos':'Fijar para todos'?></button><button class="button-ghost" name="action" value="delete">Retirar aviso</button></form><?php endif;?></article><?php endforeach;?></section></main></div></body></html>
